const body = $json.body ?? $json;
const change = body.entry?.[0]?.changes?.[0]?.value;

if (!change?.messages?.length) {
  return [{ json: { skip: true, reason: 'sem_mensagem' } }];
}

const msg = change.messages[0];
if (msg.type !== 'text') {
  return [{ json: { skip: true, reason: 'tipo_nao_suportado_' + msg.type } }];
}

return [{ json: {
  skip: false,
  from: msg.from,
  messageText: msg.text.body,
  messageId: msg.id,
  contactName: change.contacts?.[0]?.profile?.name || msg.from,
  timestamp: msg.timestamp
} }];

// Monta contexto dinamico compacto a partir dos dados Trinks
const source = $('Parse Payload Meta').item.json;
const slotsRaw = $('Trinks: Horarios Hoje').item.json;
const profsRaw = $('Trinks: Profissionais').item.json;

// === SLOTS ===
let slots = '';
if (slotsRaw.data && Array.isArray(slotsRaw.data)) {
  const today = new Date().toISOString().split('T')[0];
  const available = slotsRaw.data.filter(p => p.horariosVagos?.length > 0);
  if (available.length > 0) {
    slots = `HORARIOS VAGOS ${today}:\n`;
    for (const p of available) {
      slots += `- ${p.nome}: ${p.horariosVagos.join(', ')}\n`;
    }
  } else {
    slots = `HORARIOS VAGOS ${today}: Nenhum disponivel hoje.`;
  }
} else {
  slots = 'HORARIOS: Erro ao consultar. Peca ao cliente o dia desejado.';
}

// === PROFISSIONAIS (compacto: nome | funcao) ===
let profs = '';
if (profsRaw.data && Array.isArray(profsRaw.data)) {
  profs = 'PROFISSIONAIS ATIVOS:\n';
  for (const p of profsRaw.data) {
    const nome = p.apelido || p.nome;
    profs += `- ${nome} (ID ${p.id})\n`;
  }
} else {
  profs = 'PROFISSIONAIS: Erro ao consultar.';
}

return [{ json: {
  ...source,
  dynamicContext: `${slots}\n${profs}`
} }];

