const raw = $json;
const source = $('Parse Payload Meta').item.json;

let response = '';
if (typeof raw === 'string') response = raw;
else if (raw.output) response = String(raw.output);
else if (raw.choices?.[0]?.message?.content) response = raw.choices[0].message.content;
else if (raw.response) response = String(raw.response);
else if (raw.text) response = String(raw.text);
else if (typeof raw.content === 'string') response = raw.content;
else if (Array.isArray(raw.content) && raw.content[0]?.text) response = raw.content[0].text;

if (!response) {
  return [{ json: { ...source, tessResponse: 'Ola! Estou com uma dificuldade tecnica. Nosso atendimento humano entrara em contato em breve!', hasBookingAction: false } }];
}

response = response.trim();
let bookingRequest = null, bookingConfirm = null, clientMessage = response;

const reqMatch = response.match(/\[BOOKING_REQUEST\]\s*\n?({[\s\S]*?})/i);
if (reqMatch) {
  try { bookingRequest = JSON.parse(reqMatch[1]); clientMessage = response.replace(reqMatch[0], '').trim(); } catch(e) {}
}

const confMatch = response.match(/\[BOOKING_CONFIRM\]\s*\n?({[\s\S]*?})/i);
if (confMatch) {
  try { bookingConfirm = JSON.parse(confMatch[1]); clientMessage = clientMessage.replace(confMatch[0], '').trim(); } catch(e) {}
}

return [{ json: {
  ...source,
  tessResponse: clientMessage || response,
  bookingRequest, bookingConfirm,
  hasBookingAction: !!(bookingRequest || bookingConfirm)
} }];

const data = $json;
const TRINKS = $env.TRINKS_API_BASE_URL || 'https://api.trinks.com/v1';
const KEY = $env.TRINKS_API_KEY;
const headers = { 'X-Api-Key': KEY, 'estabelecimentoId': String($env.TRINKS_SALON_ID || '') };

let result = null;
try {
  if (data.bookingRequest?.action === 'check_availability') {
    const date = data.bookingRequest.date;
    const resp = await fetch(`${TRINKS}/agendamentos/profissionais/${date}`, { headers });
    const json = await resp.json();
    let txt = `HORARIOS ${date}:\n`;
    let found = false;
    if (json.data) {
      for (const p of json.data) {
        if (data.bookingRequest.professional_id && p.id !== data.bookingRequest.professional_id) continue;
        if (p.horariosVagos?.length) {
          found = true;
          txt += `- ${p.nome}: ${p.horariosVagos.join(', ')}\n`;
        }
      }
    }
    if (!found) txt += 'Nenhum horario disponivel.';
    result = { type: 'availability', slots: txt };
  } else if (data.bookingConfirm?.action === 'create_booking') {
    result = { type: 'booking_pending', message: `Booking para ${data.bookingConfirm.client_name}: ${data.bookingConfirm.service_name} em ${data.bookingConfirm.date_time}. Pendente ServicoEstabelecimentoId.` };
  }
} catch (err) {
  result = { type: 'error', message: err.message };
}

return [{ json: { ...data, bookingResult: result, needsSecondCall: result?.type === 'availability' } }];

